def transform(grid):
    h, w = len(grid), len(grid[0])

    # A full nonzero row separates two stacked panels.
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            top, bottom = grid[:r], grid[r + 1:]
            if len(top) == len(bottom):
                return [
                    [2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)]
                    for ra, rb in zip(top, bottom)
                ]

    # A full nonzero column separates two side-by-side panels.
    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if all(len(a) == len(b) for a, b in zip(left, right)):
                return [
                    [2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)]
                    for ra, rb in zip(left, right)
                ]

    return grid
